mapper.select:
SELECT f.fee_id, f.student_id, u.name AS student_name, f.class_id, c.class_name, f.billing_month, f.fee_amount, f.discount_amount, f.fee_amount - f.discount_amount AS billable_amount, f.due_date, f.status_code, f.description, p.last_payment_id, COALESCE(p.paid_sum, 0) AS paid_sum FROM fees f JOIN students s ON s.student_id = f.student_id JOIN users u ON u.user_id = s.user_id LEFT JOIN classes c ON c.class_id = f.class_id
LEFT JOIN (SELECT fee_id, MAX(payment_id) AS last_payment_id, SUM(paid_amount) AS paid_sum FROM fee_payments WHERE cancel_yn = 'N' GROUP BY fee_id) p ON p.fee_id = f.fee_id
ORDER BY f.billing_month DESC, f.due_date ASC, f.fee_id ASC LIMIT #{size} OFFSET #{offset}

SELECT EXISTS (
    SELECT 1
      FROM fees
     WHERE student_id    = #{studentId}
       AND billing_month = #{billingMonth}
       AND class_id IS NOT DISTINCT FROM #{classId}
)

mapper.update:
UPDATE fees
   SET status_code = #{statusCode}
 WHERE fee_id = #{feeId}

UPDATE fee_payments
   SET cancel_yn = 'Y'
 WHERE payment_id = #{paymentId}

mapper.select:
SELECT f.billing_month, COALESCE(SUM(f.fee_amount - f.discount_amount), 0) AS total_amount, COALESCE(SUM(COALESCE(p.paid_sum, 0)), 0) AS paid_amount, COUNT(*) FILTER (WHERE f.status_code = 'PAID') AS paid_count, COUNT(*) FILTER (WHERE f.status_code = 'UNPAID') AS unpaid_count, COUNT(*) FILTER (WHERE f.status_code = 'SCHEDULED') AS scheduled_count FROM fees f LEFT JOIN (SELECT fee_id, SUM(paid_amount) AS paid_sum FROM fee_payments WHERE cancel_yn = 'N' GROUP BY fee_id) p ON p.fee_id = f.fee_id WHERE f.billing_month BETWEEN #{fromMonth} AND #{toMonth}
AND f.class_id = #{classId}
GROUP BY f.billing_month ORDER BY f.billing_month ASC
